class Solution {
    std::vector<int> tree;
    std::vector<bool> lazy;

    void build(int node, int l, int r, const std::vector<int>& nums1) {
        if (l == r) {
            tree[node] = nums1[l];
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid, nums1);
        build(2 * node + 1, mid + 1, r, nums1);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    void update(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) {
            tree[node] = (r - l + 1) - tree[node];
            lazy[node] = !lazy[node];
            return;
        }
        int mid = (l + r) / 2;
        if (lazy[node]) {
            lazy[node] = false;
            tree[2 * node] = (mid - l + 1) - tree[2 * node];
            lazy[2 * node] = !lazy[2 * node];
            tree[2 * node + 1] = (r - mid) - tree[2 * node + 1];
            lazy[2 * node + 1] = !lazy[2 * node + 1];
        }
        if (ql <= mid) update(2 * node, l, mid, ql, qr);
        if (qr > mid) update(2 * node + 1, mid + 1, r, ql, qr);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

public:
    std::vector<long long> handleQuery(std::vector<int>& nums1, std::vector<int>& nums2, std::vector<std::vector<int>>& queries) {
        int n = nums1.size();
        tree.assign(4 * n, 0);
        lazy.assign(4 * n, false);
        build(1, 0, n - 1, nums1);

        long long total_sum = 0;
        for (int x : nums2) total_sum += x;

        std::vector<long long> ans;
        for (const auto& q : queries) {
            if (q[0] == 1) {
                update(1, 0, n - 1, q[1], q[2]);
            } else if (q[0] == 2) {
                total_sum += (long long)tree[1] * q[1];
            } else {
                ans.push_back(total_sum);
            }
        }
        return ans;
    }
};

class Solution {
    private int[] tree;
    private boolean[] lazy;

    private void build(int node, int l, int r, int[] nums1) {
        if (l == r) {
            tree[node] = nums1[l];
            return;
        }
        int mid = (l + r) / 2;
        build(2 * node, l, mid, nums1);
        build(2 * node + 1, mid + 1, r, nums1);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    private void update(int node, int l, int r, int ql, int qr) {
        if (ql <= l && r <= qr) {
            tree[node] = (r - l + 1) - tree[node];
            lazy[node] = !lazy[node];
            return;
        }
        int mid = (l + r) / 2;
        if (lazy[node]) {
            lazy[node] = false;
            tree[2 * node] = (mid - l + 1) - tree[2 * node];
            lazy[2 * node] = !lazy[2 * node];
            tree[2 * node + 1] = (r - mid) - tree[2 * node + 1];
            lazy[2 * node + 1] = !lazy[2 * node + 1];
        }
        if (ql <= mid) update(2 * node, l, mid, ql, qr);
        if (qr > mid) update(2 * node + 1, mid + 1, r, ql, qr);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    public long[] handleQuery(int[] nums1, int[] nums2, int[][] queries) {
        int n = nums1.length;
        tree = new int[4 * n];
        lazy = new boolean[4 * n];
        build(1, 0, n - 1, nums1);

        long totalSum = 0;
        for (int x : nums2) totalSum += x;

        java.util.List<Long> ansList = new java.util.ArrayList<>();
        for (int[] q : queries) {
            if (q[0] == 1) {
                update(1, 0, n - 1, q[1], q[2]);
            } else if (q[0] == 2) {
                totalSum += (long) tree[1] * q[1];
            } else {
                ansList.add(totalSum);
            }
        }
        long[] ans = new long[ansList.size()];
        for (int i = 0; i < ans.length; i++) ans[i] = ansList.get(i);
        return ans;
    }
}

var handleQuery = function(nums1, nums2, queries) {
    const n = nums1.length;
    const tree = new Int32Array(4 * n);
    const lazy = new Uint8Array(4 * n);

    function build(node, l, r) {
        if (l === r) {
            tree[node] = nums1[l];
            return;
        }
        const mid = (l + r) >> 1;
        build(2 * node, l, mid);
        build(2 * node + 1, mid + 1, r);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    function update(node, l, r, ql, qr) {
        if (ql <= l && r <= qr) {
            tree[node] = (r - l + 1) - tree[node];
            lazy[node] = lazy[node] ? 0 : 1;
            return;
        }
        const mid = (l + r) >> 1;
        if (lazy[node]) {
            lazy[node] = 0;
            tree[2 * node] = (mid - l + 1) - tree[2 * node];
            lazy[2 * node] = lazy[2 * node] ? 0 : 1;
            tree[2 * node + 1] = (r - mid) - tree[2 * node + 1];
            lazy[2 * node + 1] = lazy[2 * node + 1] ? 0 : 1;
        }
        if (ql <= mid) update(2 * node, l, mid, ql, qr);
        if (qr > mid) update(2 * node + 1, mid + 1, r, ql, qr);
        tree[node] = tree[2 * node] + tree[2 * node + 1];
    }

    build(1, 0, n - 1);
    let totalSum = 0;
    for (let i = 0; i < n; i++) totalSum += nums2[i];

    const ans = [];
    for (let i = 0; i < queries.length; i++) {
        const q = queries[i];
        if (q[0] === 1) {
            update(1, 0, n - 1, q[1], q[2]);
        } else if (q[0] === 2) {
            totalSum += tree[1] * q[1];
        } else {
            ans.push(totalSum);
        }
    }
    return ans;
};
